function navigate(next: { tab?: string; category?: string; q?: string }) {
    const nextQ = next.q ?? q;
    const nextCategory = next.category ?? category;
    const params = new URLSearchParams({
      tab: next.tab ?? tab,
      ...(nextQ ? { q: nextQ } : {}),
      ...(nextCategory ? { category: nextCategory } : {}),
    });
